from itertools import combinations
def ext(graphs,k):
    out=[]
    for adj in graphs:
        for nb in range(1<<k):
            if any(adj[i]&nb for i in range(k) if nb>>i&1): continue  # neighbourhood must be independent (no triangle)
            new=adj+[nb]
            for i in range(k):
                if nb>>i&1: new[i]=adj[i]|(1<<k)
            non=[i for i in range(k) if not nb>>i&1]
            bad=False
            for a,b,c in combinations(non,3):
                if not (new[a]>>b&1 or new[a]>>c&1 or new[b]>>c&1): bad=True;break
            if not bad: out.append(new)
    return out
