def matchable(rem):
    B=[c for c in rem if (c[0]+c[1])%2==0]; W=set(rem)-set(B)
    match={}
    def aug(u,seen):
        for d in [(0,1),(1,0),(0,-1),(-1,0)]:
            v=(u[0]+d[0],u[1]+d[1])
            if v in W and v not in seen:
                seen.add(v)
                if v not in match or aug(match[v],seen):
                    match[v]=u; return True
        return False
    return len(B)==len(W) and all(aug(u,set()) for u in B)
