from functools import lru_cache
def count(m,n):
    @lru_cache(None)
    def f(col,mask):
        if col==n: return 1 if mask==0 else 0
        outs=[]
        def fill(row,cur,nxt):
            if row==m: outs.append(nxt); return
            if cur>>row&1: fill(row+1,cur,nxt)
            else:
                fill(row+1,cur,nxt|1<<row)
                if row+1<m and not cur>>(row+1)&1: fill(row+2,cur,nxt)
        fill(0,mask,0)
        return sum(f(col+1,x) for x in outs)
    return f(0,0)
