def tileable(rem):
    if not rem: return True
    c=min(rem)
    for sh in [((0,0),(0,1),(0,2)),((0,0),(1,0),(2,0))]:
        pts={(c[0]+a,c[1]+b) for a,b in sh}
        if pts<=rem and tileable(rem-pts): return True
    return False
