def ltile(n,r0,c0,hole,tiles):
    if n==1:
        tiles.append({(r0+a,c0+b) for a in (0,1) for b in (0,1)}-{hole}); return
    h=2**(n-1); centre=[]
    for qa in (0,1):
        for qb in (0,1):
            R,C=r0+qa*h,c0+qb*h
            if R<=hole[0]<R+h and C<=hole[1]<C+h: sub=hole
            else:
                sub=(r0+h-1+qa,c0+h-1+qb); centre.append(sub)
            ltile(n-1,R,C,sub,tiles)
    tiles.append(set(centre))
for n in range(1,5):
    N=2**n
    for hole in [(r,c) for r in range(N) for c in range(N)]:
        T=[]; ltile(n,0,0,hole,T)
        cov=[x for t in T for x in t]
        assert len(cov)==len(set(cov))==N*N-1 and hole not in cov
        for t in T:
            rs={x[0] for x in t}; cs={x[1] for x in t}
            assert len(t)==3 and max(rs)-min(rs)==1 and max(cs)-min(cs)==1
    assert (4**n-1)%3==0
def tile(rem,shapes):
    if not rem: return True
    c=min(rem)
    for sh in shapes:
        m=min(sh); pts={(c[0]+a-m[0],c[1]+b-m[1]) for a,b in sh}
        if pts<=rem and tile(rem-pts,shapes): return True
    return False
