import random
from itertools import combinations
def orient(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
def in_tri(p,a,b,c):
    s=[orient(a,b,p),orient(b,c,p),orient(c,a,p)]
    return all(x>0 for x in s) or all(x<0 for x in s)
def convex4(Q):
    return not any(in_tri(Q[i],*[Q[j] for j in range(4) if j!=i]) for i in range(4))
random.seed(5)
for _ in range(3000):
    P=[(random.random(),random.random()) for _ in range(5)]
    assert any(convex4(list(Q)) for Q in combinations(P,4))
assert not convex4([(0,0),(4,0),(0,4),(1,1)])

