import random
from itertools import permutations
def longest(seq,cmp):
    best=[1]*len(seq)
    for i in range(len(seq)):
        for j in range(i):
            if cmp(seq[j],seq[i]): best[i]=max(best[i],best[j]+1)
    return max(best)
mono=lambda s: max(longest(s,lambda a,b:a<b),longest(s,lambda a,b:a>b))
